            perfboardMm: `${(dims.perfboardWidthCm * 10).toFixed(2)} x ${(dims.perfboardHeightCm * 10).toFixed(2)} x ${(dims.perfboardThicknessCm * 10).toFixed(1)} (${dims.perfboardCols}x${dims.perfboardRows})`,
