        ctx.fillRect(25, 24, 7, 2);
        ctx.fillStyle = "#57606F";
        ctx.beginPath();
        ctx.arc(17, 33, 6, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = "#747D8C";
        ctx.beginPath();
        ctx.arc(33, 36, 2.2, 0, Math.PI * 2);
        ctx.arc(38, 33, 2.2, 0, Math.PI * 2);
