            ctx.fillStyle = "rgba(10, 24, 30, 0.6)";
            ctx.beginPath();
            ctx.roundRect(0, 0, w, h, 8);
            ctx.fill();
            ctx.strokeStyle = "rgba(95, 180, 156, 0.3)";
            ctx.lineWidth = 1;
            ctx.stroke();

            const painter = PIXEL_ART_PAINTERS[c.id];
            if (painter) painter(ctx, c);
            else drawGenericCartridgeIcon(ctx, c);
            ctx.restore();
